                | Scenario::FragmentedToolName
                | Scenario::ThinkingToolCallCleanStop
                | Scenario::ReasoningCleanStop
                | Scenario::ParallelToolCallCleanStop
                | Scenario::ZeroArgToolCallCleanStop => None,
